use hec_native_ic::{counted,fp::Fp,poly::Poly,instance::pick_instance};
#[derive(Clone,Debug,PartialEq,Eq)]struct P(Vec<u64>);
impl P{fn new(mut v:Vec<u64>)->Self{while v.last()==Some(&0){v.pop();}Self(v)}fn one()->Self{Self(vec![1])}fn deg(&self)->usize{self.0.len()-1}fn add(&self,b:&Self,f:&Fp)->Self{Self::new((0..self.0.len().max(b.0.len())).map(|i|f.add(*self.0.get(i).unwrap_or(&0),*b.0.get(i).unwrap_or(&0))).collect())}fn scale(&self,k:u64,f:&Fp)->Self{Self::new(self.0.iter().map(|&x|f.mul(x,k)).collect())}fn mul(&self,b:&Self,f:&Fp)->Self{if self.0.is_empty()||b.0.is_empty(){return Self(vec![]);}let mut v=vec![0;self.0.len()+b.0.len()-1];for(i,&x)in self.0.iter().enumerate(){for(j,&y)in b.0.iter().enumerate(){v[i+j]=f.add(v[i+j],f.mul(x,y));}}Self::new(v)}fn pow(&self,n:usize,f:&Fp)->Self{(0..n).fold(Self::one(),|a,_|a.mul(self,f))}fn div(&self,b:&Self,f:&Fp)->(Self,Self){assert!(!b.0.is_empty());let mut r=self.clone();let mut q=vec![0;self.0.len().saturating_sub(b.0.len())+1];let il=f.inv(*b.0.last().unwrap());while !r.0.is_empty()&&r.deg()>=b.deg(){let n=r.deg()-b.deg();let k=f.mul(*r.0.last().unwrap(),il);q[n]=k;for i in 0..b.0.len(){r.0[n+i]=f.sub(r.0[n+i],f.mul(k,b.0[i]));}r=Self::new(r.0);} (Self::new(q),r)}fn exact(&self,b:&Self,f:&Fp)->Self{let(q,r)=self.div(b,f);assert!(r.0.is_empty());q}fn deriv(&self,f:&Fp)->Self{Self::new((1..self.0.len()).map(|i|f.mul(i as u64,self.0[i])).collect())}fn monic(&self,f:&Fp)->Self{self.scale(f.inv(*self.0.last().unwrap()),f)}fn gcd(&self,b:&Self,f:&Fp)->Self{let(mut a,mut b)=(self.clone(),b.clone());while !b.0.is_empty(){let r=a.div(&b,f).1;a=b;b=r;}a.monic(f)}fn eval(&self,t:u64,f:&Fp)->u64{self.0.iter().rev().fold(0,|a,&x|f.add(f.mul(a,t),x))}}
fn arr(l:&str,k:&str)->P{P::new(l.split(&format!("{k}=[")).nth(1).unwrap().split(']').next().unwrap().split(',').map(|x|x.trim().parse().unwrap()).collect())}
fn native(p:&P)->Poly{Poly::from_coeffs(&p.0)}
fn sqrt(p:&P,f:&Fp)->P{assert_eq!(p.deg()%2,0);let n=p.deg()/2;let lead=f.sqrt(*p.0.last().unwrap()).expect("nonsquare quotient scalar");let mut v=vec![0;n+1];v[n]=lead;let den=f.inv(f.mul(2,lead));for i in(0..n).rev(){let sq=P(v.clone()).pow(2,f);let known=*sq.0.get(n+i).unwrap_or(&0);v[i]=f.mul(f.sub(p.0[n+i],known),den);}let out=P::new(v);assert_eq!(out.pow(2,f),*p);out}
fn disc(a:&P,c:&P,d2:&P,e:&P,f:&Fp)->P{let terms=[(256,a.pow(3,f).mul(&e.pow(3,f),f)),(-128,a.pow(2,f).mul(&c.pow(2,f),f).mul(&e.pow(2,f),f)),(144,a.pow(2,f).mul(c,f).mul(d2,f).mul(e,f)),(-27,a.pow(2,f).mul(&d2.pow(2,f),f)),(16,a.mul(&c.pow(4,f),f).mul(e,f)),(-4,a.mul(&c.pow(3,f),f).mul(d2,f))];terms.iter().fold(P(vec![]),|s,(k,p)|s.add(&p.scale(f.from_i64(*k),f),f))}
use std::collections::{BTreeMap,BTreeSet};
type B=BTreeMap<(i32,i32),u64>;
fn put(b:&mut B,e:(i32,i32),v:u64,f:&Fp){let v=f.add(*b.get(&e).unwrap_or(&0),v);if v==0{b.remove(&e);}else{b.insert(e,v);}}
fn choose(n:usize,k:usize,f:&Fp)->u64{let mut v=1;for i in 0..k{v=f.mul(v,f.mul((n-i)as u64,f.inv((i+1)as u64)));}v}
fn blow(b:&B,c:u64,m:i32,f:&Fp)->B{let mut out=B::new();for(&(i,j),&v)in b{assert!(j>=0);for k in 0..=j{let a=f.mul(v,f.mul(choose(j as usize,k as usize,f),f.pow(c,(j-k)as u64)));put(&mut out,(i+j-m,k),a,f);}}out}
fn multiplicity(b:&B)->i32{assert!(!b.is_empty());b.keys().map(|&(i,j)|i+j).min().unwrap()}
fn tangent(b:&B,m:i32)->P{let mut v=vec![0;m as usize+1];for(&(i,j),&c)in b{assert!(i>=0&&j>=0);if i+j==m{v[j as usize]=c;}}P::new(v)}
fn add_constraints(basis:&[B],order:i32,rows:&mut Vec<Vec<u64>>){let mut exps=BTreeSet::new();for b in basis{for &e in b.keys(){if e.0<0||e.1<0||e.0+e.1<order{exps.insert(e);}}}for e in exps{let row=basis.iter().map(|b|*b.get(&e).unwrap_or(&0)).collect::<Vec<_>>();if row.iter().any(|&x|x!=0){rows.push(row);}}}
fn resolution(curve:B,basis:Vec<B>,depth:usize,f:&Fp,rows:&mut Vec<Vec<u64>>,path:&mut Vec<(i32,Option<u64>)>)->usize{assert!(depth<20,"resolution depth bound");let m=multiplicity(&curve);assert!(m>=1);if m==1{println!("SMOOTH depth={depth} local={curve:?}");return 0;}add_constraints(&basis,m-1,rows);let h=tangent(&curve,m);let vertical=m as usize-h.deg();assert!(vertical<=1,"unresolved repeated vertical tangent");let repeated=h.gcd(&h.deriv(f),f);let mut rest=repeated.clone();let mut roots=Vec::new();for c in 0..f.p{if repeated.eval(c,f)==0{roots.push(c);let lin=P::new(vec![f.neg(c),1]);while rest.div(&lin,f).1.0.is_empty(){rest=rest.exact(&lin,f);}}}assert_eq!(rest.deg(),0,"unresolved nonrational repeated tangent");assert!(roots.len()<=1,"multiple repeated chains not in this bounded implementation");let c=roots.first().copied();println!("NODE depth={depth} multiplicity={m} tangent={:?} repeated={:?} vertical_multiplicity={vertical} next={c:?} local={curve:?}",h.0,repeated.0);path.push((m,c));let mut delta=(m*(m-1)/2)as usize;if let Some(c)=c{let next=blow(&curve,c,m,f);assert!(next.keys().all(|&(i,j)|i>=0&&j>=0));let bs=basis.iter().map(|b|blow(b,c,m-1,f)).collect();delta+=resolution(next,bs,depth+1,f,rows,path);}delta}
fn nullspace(mut rows:Vec<Vec<u64>>,n:usize,f:&Fp)->(usize,Vec<Vec<u64>>){let mut rank=0;let mut pivots=Vec::new();for c in 0..n{let Some(pr)=(rank..rows.len()).find(|&r|rows[r][c]!=0)else{continue;};rows.swap(pr,rank);let z=f.inv(rows[rank][c]);for j in c..n{rows[rank][j]=f.mul(rows[rank][j],z);}for i in 0..rows.len(){if i==rank{continue;}let z=rows[i][c];for j in c..n{rows[i][j]=f.sub(rows[i][j],f.mul(z,rows[rank][j]));}}pivots.push(c);rank+=1;}let mut basis=Vec::new();for j in 0..n{if pivots.contains(&j){continue;}let mut v=vec![0;n];v[j]=1;for(i,&c)in pivots.iter().enumerate(){v[c]=f.neg(rows[i][j]);}basis.push(v);} (rank,basis)}
fn controls(){let f=Fp::new(61);for(name,curve,expected)in[("node",BTreeMap::from([((0,2),1),((2,0),60)]),1),("cusp",BTreeMap::from([((0,2),1),((3,0),60)]),1),("tacnode",BTreeMap::from([((0,2),1),((4,0),60)]),2)]{let mut path=Vec::new();let delta=resolution(curve,vec![],0,&f,&mut vec![],&mut path);assert_eq!(delta,expected);println!("CONTROL name={name} delta={delta} path={path:?}");}}
fn main(){counted::disable();controls();let raw=include_str!("../native-smith-affine/CONTROL.txt");let f=Fp::new(61);let monomials:Vec<_>=(0..=7).flat_map(|j|(0..=7-j).map(move|i|(i,j))).collect();assert_eq!(monomials.len(),36);let mut maps=0;for(idx,l)in raw.lines().enumerate().filter(|(_,l)|l.starts_with("MAP p=61 ")){let dl=raw.lines().nth(idx+1).unwrap();let a=arr(dl,"delta4");let c=arr(dl,"delta2");let e=arr(dl,"delta0");let norm=arr(l,"norm_s");let r=arr(l,"monic_square_root");let d=r.scale(f.neg(f.mul(8,f.sqrt(*norm.0.last().unwrap()).unwrap())),&f);let mut curve=B::new();for(p,offset)in[(&a,6),(&c,8),(&d,9),(&e,10)]{for(i,&v)in p.0.iter().enumerate(){put(&mut curve,(i as i32,offset-i as i32),v,&f);}}assert_eq!(multiplicity(&curve),6);let basis=monomials.iter().map(|&(i,j)|BTreeMap::from([((i,7-i-j),1)])).collect::<Vec<_>>();let mut rows=Vec::new();let mut path=Vec::new();let delta=resolution(curve,basis,0,&f,&mut rows,&mut path);let(rank,adjoints)=nullspace(rows.clone(),36,&f);for v in &adjoints{for row in &rows{assert_eq!((0..36).fold(0,|a,i|f.add(a,f.mul(row[i],v[i]))),0);}}for(i,v)in adjoints.iter().enumerate(){let terms:Vec<_>=v.iter().enumerate().filter(|(_,c)|**c!=0).map(|(j,&c)|(monomials[j],c)).collect();println!("INFINITY_ADJOINT map={maps} basis={i} terms={terms:?}");}println!("MAP map={maps} delta_infinity={delta} path={path:?} constraint_rows={} constraint_rank={rank} infinity_adjoint_dimension={} degree=7 finite_singular_constraints_pending=true",rows.len(),adjoints.len());maps+=1;}assert_eq!(maps,2);eprintln!("PASS maps=2 controls=3 exact_blowups=true complete_repeated_tangent_chains=true infinity_adjoint_constraints=true no_finite_adjoints_or_canonical_model_or_speed_claim=true");}
